/**
 * Global exception filter that formats errors as RFC 7807 Problem Details.
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 */
import {
  ArgumentsHost,
  Catch,
  ExceptionFilter,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import type { Request, Response } from 'express';
import { ProblemDetails, ValidationFieldError } from './problem-details.dto';
import { BusinessError } from './business-error';

// Every Datrix problem type is a URN under this prefix, spelled identically
// by every language target (the framework problem-type registry in
// datrix-common). A declared exception carries its own URN on errorType.
const PROBLEM_TYPE_PREFIX = 'urn:datrix:error:';

@Catch()
export class AllExceptionsFilter implements ExceptionFilter {
  private readonly logger = new Logger(AllExceptionsFilter.name);

  catch(exception: unknown, host: ArgumentsHost): void {
    const ctx = host.switchToHttp();
    const request = ctx.getRequest<Request>();
    const response = ctx.getResponse<Response>();

    const problemDetails = this.buildProblemDetails(exception, request);

    this.logger.error(
      'exception_caught status=%s type=%s path=%s',
      String(problemDetails.status),
      problemDetails.type,
      problemDetails.instance,
    );

    response
      .status(problemDetails.status)
      .header('Content-Type', 'application/problem+json')
      .json(problemDetails);
  }

  private buildProblemDetails(exception: unknown, request: Request): ProblemDetails {
    const instance = request.url;

    if (exception instanceof BusinessError) {
      return {
        type: exception.errorType,
        title: exception.errorTitle,
        status: exception.getStatus(),
        detail: exception.message,
        instance,
      };
    }

    if (exception instanceof HttpException) {
      const status = exception.getStatus();
      const exceptionResponse = exception.getResponse();

      if (status === HttpStatus.UNPROCESSABLE_ENTITY || status === HttpStatus.BAD_REQUEST) {
        const validationErrors = this.extractValidationErrors(exceptionResponse);
        if (validationErrors.length > 0) {
          return {
            type: 'urn:datrix:error:validation',
            title: 'Validation Failed',
            status,
            detail: 'Request body failed validation.',
            instance,
            errors: validationErrors,
          };
        }
      }

      return {
        type: this.statusToType(status),
        title: this.statusToTitle(status),
        status,
        detail: this.httpExceptionDetail(exception, exceptionResponse),
        instance,
      };
    }

    return {
      type: 'urn:datrix:error:internal',
      title: 'Internal Server Error',
      status: HttpStatus.INTERNAL_SERVER_ERROR,
      detail: 'An unexpected error occurred.',
      instance,
    };
  }

  private httpExceptionDetail(
    exception: HttpException,
    exceptionResponse: string | object,
  ): string {
    if (typeof exceptionResponse === 'string') {
      return exceptionResponse;
    }
    const rec = exceptionResponse as Record<string, unknown>;
    const msg = rec['message'];
    if (typeof msg === 'string') {
      return msg;
    }
    return exception.message;
  }

  private extractValidationErrors(
    response: string | object,
  ): ValidationFieldError[] {
    if (typeof response !== 'object' || response === null) {
      return [];
    }
    const resp = response as Record<string, unknown>;
    const message = resp['message'];
    if (!Array.isArray(message)) {
      return [];
    }
    return message
      .filter((m): m is string => typeof m === 'string')
      .map((m) => {
        const parts = m.split(' ');
        const field = parts[0] ?? 'unknown';
        return { field, message: m };
      });
  }

  private statusToType(status: number): string {
    const STATUS_TYPE_MAP: Record<number, string> = {
      400: 'urn:datrix:error:bad-request',
      401: 'urn:datrix:error:unauthorized',
      403: 'urn:datrix:error:forbidden',
      404: 'urn:datrix:error:not-found',
      409: 'urn:datrix:error:conflict',
      422: 'urn:datrix:error:validation',
      429: 'urn:datrix:error:rate-limit-exceeded',
      500: 'urn:datrix:error:internal',
    };
    const mapped = STATUS_TYPE_MAP[status];
    if (mapped !== undefined) {
      return mapped;
    }
    return `${PROBLEM_TYPE_PREFIX}http-${String(status)}`;
  }

  private statusToTitle(status: number): string {
    const STATUS_TITLE_MAP: Record<number, string> = {
      400: 'Bad Request',
      401: 'Unauthorized',
      403: 'Forbidden',
      404: 'Not Found',
      409: 'Conflict',
      422: 'Validation Error',
      429: 'Too Many Requests',
      500: 'Internal Server Error',
    };
    const mapped = STATUS_TITLE_MAP[status];
    if (mapped !== undefined) {
      return mapped;
    }
    return `HTTP ${String(status)}`;
  }
}
